import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { Car, Manufacturer, ManufacturerRating, Rating } from './models';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private http = inject(HttpClient);
  private root = '/api';

  getManufacturers(): Observable<Manufacturer[]> { return this.http.get<Manufacturer[]>(`${this.root}/manufacturers`); }
  saveManufacturer(m: Manufacturer): Observable<Manufacturer> { return this.http.post<Manufacturer>(`${this.root}/manufacturers`, m); }
  deleteManufacturer(id: number): Observable<void> { return this.http.delete<void>(`${this.root}/manufacturers/${id}`); }
  getAverageRatings(): Observable<ManufacturerRating[]> { return this.http.get<ManufacturerRating[]>(`${this.root}/manufacturers/ratings`); }

  getRatings(): Observable<Rating[]> { return this.http.get<Rating[]>(`${this.root}/ratings`); }
  saveRating(r: Rating): Observable<Rating> { return this.http.post<Rating>(`${this.root}/ratings`, r); }
  deleteRating(id: number): Observable<void> { return this.http.delete<void>(`${this.root}/ratings/${id}`); }

  getCars(): Observable<Car[]> { return this.http.get<Car[]>(`${this.root}/cars`, { params: { offset: 0, limit: -1 } }); }
}
