import { Injectable, signal } from '@angular/core';

export interface Message { key: number; text: string; style: 'success' | 'error'; }

@Injectable({ providedIn: 'root' })
export class MessageService {
  private seq = 0;
  readonly messages = signal<Message[]>([]);

  show(text: string, style: 'success' | 'error', delay = 5000): void {
    const key = ++this.seq;
    this.messages.update((m) => [...m, { key, text, style }]);
    if (delay > 0) {
      setTimeout(() => this.close(key), delay);
    }
  }
  success(text: string): void { this.show(text, 'success'); }
  error(text: string): void { this.show(text, 'error'); }
  close(key: number): void {
    this.messages.update((m) => m.filter((x) => x.key !== key));
  }
}
