import { Component, inject, OnInit, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService } from './api.service';
import { MessageService } from './message.service';
import { Car, Rating, carLabel } from './models';

@Component({
  selector: 'app-rating',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="big-title">
      <h2>Ratings</h2>
      <button id="gwt-debug-ratingCreate" class="add-action" (click)="create()">Create</button>
    </div>
    <table id="gwt-debug-ratings" class="grid">
      <thead><tr><th>ID</th><th>Car</th><th>Rating</th><th>Delete</th></tr></thead>
      <tbody>
        @for (r of items(); track r.id) {
          <tr>
            <td>{{ r.id }}</td><td>{{ label(r) }}</td><td>{{ r.rating }}</td>
            <td><button (click)="remove(r)">Delete</button></td>
          </tr>
        }
      </tbody>
    </table>
    @if (showForm()) {
      <div class="glass" (click)="close()"></div>
      <div class="popup">
        <div><span>Car:</span>
          <select [(ngModel)]="car">
            @for (c of cars(); track c.id) { <option [ngValue]="c">{{ carLabel(c) }}</option> }
          </select>
        </div>
        <div><span>Your rating:</span>
          <input id="gwt-debug-ratingInput" type="number" maxlength="3" [(ngModel)]="value">
        </div>
        <div>
          <button id="gwt-debug-ratingSave" (click)="save()">Save</button>
          <button (click)="close()">Close</button>
        </div>
      </div>
    }
  `,
})
export class RatingComponent implements OnInit {
  private api = inject(ApiService);
  private msg = inject(MessageService);
  items = signal<Rating[]>([]);
  cars = signal<Car[]>([]);
  showForm = signal(false);
  car: Car | null = null;
  value: number | null = null;
  carLabel = carLabel;

  label(r: Rating): string { return carLabel(r.car); }

  ngOnInit(): void {
    this.api.getRatings().subscribe({
      next: (l) => this.items.set(l),
      error: () => this.msg.error('Failed to load ratings'),
    });
  }
  create(): void {
    this.api.getCars().subscribe({
      next: (c) => {
        this.cars.set(c);
        this.car = c[0] ?? null;
        this.value = null;
        this.showForm.set(true);
      },
      error: () => this.msg.error('Failed to load cars'),
    });
  }
  close(): void { this.showForm.set(false); }
  save(): void {
    this.api.saveRating({ car: this.car, rating: this.value }).subscribe({
      next: (saved) => {
        this.items.update((l) => [...l, saved]);
        this.msg.success('Rating saved');
        this.close();
      },
      error: () => this.msg.error('Failed to save rating'),
    });
  }
  remove(r: Rating): void {
    if (!window.confirm('Are you sure you want to delete' + carLabel(r.car) + '?')) return;
    this.api.deleteRating(r.id!).subscribe({
      next: () => this.items.update((l) => l.filter((x) => x.id !== r.id)),
      error: () => this.msg.error('Failed to delete rating'),
    });
  }
}
