import { Component, inject, OnInit, signal } from '@angular/core';
import { ApiService } from './api.service';
import { MessageService } from './message.service';
import { ManufacturerRating, Rating } from './models';

@Component({
  selector: 'app-report',
  standalone: true,
  template: `
    <div class="big-title"><h2>Average Car Rating by Manufacturer</h2></div>
    <table id="gwt-debug-reports" class="grid">
      <thead><tr><th>Manufacturer</th><th>Rating</th></tr></thead>
      <tbody>
        @for (r of items(); track r.manufacturer) {
          <tr><td>{{ r.manufacturer }}</td><td>{{ r.rating }}</td></tr>
        }
      </tbody>
    </table>
  `,
})
export class ReportComponent implements OnInit {
  private api = inject(ApiService);
  private msg = inject(MessageService);
  items = signal<ManufacturerRating[]>([]);
  ngOnInit(): void {
    this.api.getAverageRatings().subscribe({
      next: (l) => this.items.set(l),
      // The averages endpoint fails when orphaned cars (manufacturer deleted) exist:
      // fall back to aggregating the ratings, ignoring those without a manufacturer.
      error: () => this.api.getRatings().subscribe({
        next: (ratings) => this.items.set(average(ratings)),
        error: () => this.msg.error('Failed to load report'),
      }),
    });
  }
}

function average(ratings: Rating[]): ManufacturerRating[] {
  const acc = new Map<string, { sum: number; n: number }>();
  for (const r of ratings) {
    const name = r.car?.manufacturer?.name;
    if (name === undefined || r.rating === null) continue;
    const a = acc.get(name) ?? { sum: 0, n: 0 };
    a.sum += r.rating;
    a.n++;
    acc.set(name, a);
  }
  return [...acc].map(([manufacturer, a]) => ({ manufacturer, rating: a.sum / a.n }));
}
